{"catalogue_hash":"c13388a27643c4cf048024f92e1d42e673e71316324e781ed618957e76dedbf1","composition":"Combine atomic objectives in the objectives array. mixed and multi_object are compositions, never kind values.","constraint_grammar":{"field_operators":["eq","neq","in","lt","lte","gt","gte"],"registered_predicates":{"eligible_for_case":["line"],"has_valid_evidence":["line"],"registered_event_exists":["line"],"requires_approval":["line"],"within_case_window":["line"]}},"contract_version":"world-grounded-contract-v2","domain":"aftersales","entity_types":{"customer":[],"evidence":["issue","simulated_valid"],"external_event":["at","kind","outcome"],"line":["quantity","status","unit_price_cents"],"order":["delivered_at","paid_cents","payment_channel","status"],"product":["replacement_days","return_days","return_required","returnable","stock"],"profile":["issue"]},"event_outcomes":{"manager_review":["approved","denied"],"return_received":["missing","received"]},"event_selection":"Binding an external_event variable only inspects that registered event. Only external_event_constraints with required=true schedule it. required=false asserts that no matching registered event exists; it does not mean skip a present event.","field_contracts":{"customer":{},"evidence":{"issue":{"operators":["eq","neq","in"],"value_schema":{"enum":["damaged","wrong_item","missing_parts"],"type":"string"}},"simulated_valid":{"operators":["eq","neq","in"],"value_schema":{"type":"boolean"}}},"external_event":{"at":{"operators":["eq","neq","in","lt","lte","gt","gte"],"value_schema":{"format":"date-time","type":"string"}},"kind":{"operators":["eq","neq","in"],"value_schema":{"enum":["manager_review","return_received"],"type":"string"}},"outcome":{"operators":["eq","neq","in"],"value_schema":{"enum":["approved","denied","received","missing"],"type":"string"}}},"line":{"quantity":{"operators":["eq","neq","in","lt","lte","gt","gte"],"value_schema":{"type":"integer"}},"status":{"operators":["eq","neq","in"],