ice and irreversible settlement require the applicable exact customer confirmation. Use the original payment channel and remaining paid value."],"catalogue_hash":"7faf63ebb0aeabf1880e5cf49e9178a9cbeae0ee3dcdc1b7bfe874c5a4274693","domain":"aftersales","errors":{"AFTERSALES_WINDOW_EXPIRED":"Create/agree remedies only inside the product return window following actual delivery.","ALREADY_RESOLVED":"A line can be settled only once; another order or stale agreement cannot be substituted.","APPROVAL_REQUIRED":"Refunds over the merchant support limit require a simulated manager approval; agents cannot assert approval.","CASE_SCOPE_MISMATCH":"Case scope mismatch. Consult the applicable current public contract and resource facts.","CUSTOMER_CONTEXT_REQUIRED":"Customer context required. Consult the applicable current public contract and resource facts.","DELIVERY_DEADLINE_UNMET":"Delivery deadline unmet. Consult the applicable current public contract and resource facts.","EVIDENCE_INVALID":"Evidence invalid. Consult the applicable current public contract and resource facts.","EVIDENCE_REQUIRED":"Damage, wrong-item and missing-parts remedies require independently verified evidence bound to the line and issue.","EVIDENCE_SCOPE_MISMATCH":"Evidence scope mismatch. Consult the applicable current public contract and resource facts.","EXPLICIT_CONSENT_REQUIRED":"Irreversible settlement needs current exact consent to the actual quote; revised preferences invalidate old quotes.","INVALID_WORLD":"Invalid world. Consult the applicable current public contract and resource facts.","LINE_SCOPE_MISMATCH":"Line scope mismatch. Consult the applicable current public contract and resource facts.","MERCHANT_NOT_FOUND":"Merchant not found. Consult the applicable current public contract and resource facts.","MERCHANT_SCOPE_MISMATCH":"Merchant scope mismatch. Consult the applicable current public contract and resource facts.","ORDER_ACCESS_DENIED":"Only the authenticated buyer may service their order; merchant scope is explicit.","ORDER_NOT_DELIVERED":"Order not delivered. Consult the applicable current public contract and resource facts.","ORDER_NOT_FOUND":"Order not found. Consult the applicable current public contract and resource facts.","ORIGINAL_CHANNEL_REQUIRED":"Refunds return to the original paid channel and never exceed eligible paid line value.","PICKUP_ALREADY_SCHEDULED":"Pickup already scheduled. Consult the applicable current public contract and resource facts.","PICKUP_CONFIRMATION_REQUIRED":"Pickup confirmation required. Consult the applicable current public contract and resource facts.","PREFERENCE_RESOLUTION_REQUIRED":"Preference resolution required. Consult the applicable current public contract and resource facts.","PRODUCT_NOT_RETURNABLE":"Product not returnable. Consult the applicable current public contract and resource facts.","QUOTE_EXPIRED":"Quote expired. Consult the applicable current public contract and resource facts.","QUOTE_SCOPE_MISMATCH":"Quote scope mismatch. Consult the applicable current public contract and resource facts.","REFUND_EXCEEDS_PAYMENT":"Refund exceeds payment. Consult the applicable current public contract and resource facts.","REFUND_NOT_AGREED":"Refund not agreed. Consult the applicable current public contract and resource facts.","REPLACEMENT_UNAVAILABLE":"Replacement stock is conserved; promised delivery must meet the stated deadline.","REQUIRED_INFORMATION_MISSING":"Select the order/line and state the issue before opening a case; disclose required evidence held by the customer.","RETURN_NOT_AGREED":"Return not agreed. Consult the applicable current public contract and resource facts.","RETURN_RECEIPT_REQUIRED":"A return-required refund settles only after independently attested physical receipt.","STALE_CUSTOMER_CHOICE":"Stale customer choice. Consult the applicable current public contract and resource facts.","UNKNOWN_ACTOR":"Unknown actor. Consult the applicable current public contract and resource facts."},"protocol":"eight-domain-public-rulebook-v1","rules_version":"aftersales-0.1.0","scope":"Static public policy and code vocabulary; not the expected answer for any particular world or task."},"objective_contracts":{"correct_refusal":{"operation":"open_case"},"created_object_completion":{"accepted_values":["open","evidence_verified"],"collection":"cases","field":"status"},"existing_object_completion":{"accepted_values":["return_pending","refunded","exchanged","reshipped"],"collection":"lines","field":"status"}},"objective_types":["existing_object_completion","created_object_completion","correct_refusal"],"pool_commitment":"4b441ee6fd1df8beb945a1f5b9f58f484e4919448e832b2f0784d45035c85a42","protocol":"world-grounded-domain-catalogue-v2","relationship_pairs":{"distinct":[["customer","customer"],["evidence","evidence"],["external_event","external_event"],["line","line"],["order","order"],["product","product"],["profile","profile"]],"event_for_line":[["external_event","line"],["line","external_event"]],"profile_for_line":[["line","profile"],["profile","line"]],"references":[["evidence","line"],["external_event","line"],["line","order"],["line","product"],["order","customer"],["profile","evidence"],["profile","line"],["profile","order"]],"same_identity":[["customer","customer"],["customer","profile"],["profile","customer"],["profile","profile"]],"same_owner":[["line","line"],["line","order"],["line","profile"],["order","line"],["order","order"],["order","profile"],["profile","line"],["profile","order"],["profile","profile"]]},"relationships":["distinct","same_identity","same_owner","references","profile_for_line","event_for_line"],"rules_version":"aftersales-0.1.0","scope_contract":"Every objective targets a line alias explicitly linked to a profile alias by profile_for_line. All bound customer, profile, order, line, evidence and event objects belong to that same authenticated identity. Products must be referenced by its lines. Information, preferences and scheduled events refer only to objective profiles/lines.","world_pool_coverage":{"aggregate_entity_count_ranges":{"approvals":{"max":0,"min":0},"cases":{"max":0,"min":0},"evidence":{"max":31,"min":20},"external_events":{"max":62,"min":40},"interaction":{"max":6,"min":6},"lines":{"max":31,"min":20},"merchants":{"max":2,"min":2},"orders":{"max":15,"min":11},"products":{"max":10,"min":7},"profiles":{"max":31,"min":20},"quotes":{"max":0,"min":0},"refunds":{"max":0,"min":0},"replacements":{"max":0,"min":0},"returns":{"max":0,"min":0},"users":{"max":4,"min":4}},"authorized_partitions":["train"],"distinct_permission_structures":3,"distinct_structures":3,"scope":"Aggregate structure only; no world IDs, object IDs, per-world states, witnesses, Oracle labels, or service outcomes.","world_count":3}}

